#!/usr/bin/env python3
"""Independent reference implementation of the protocol (slow, brute force)."""
import json
import sys
import itertools
from fractions import Fraction

GTAB = ((0, 0, 1), (1, 1, 2), (1, 1, 2))
UNIFORM = (Fraction(1, 3),) * 3


def canon(a, b):
    return (a, b) if a < b else (b, a)


def norm(path, ixps):
    kept = [a for a in path if a not in ixps]
    out = []
    for a in kept:
        if not out or out[-1] != a:
            out.append(a)
    return out


class Invalid(Exception):
    pass


def check(cond):
    if not cond:
        raise Invalid()


def validate(data):
    check(type(data) is dict)
    check(set(data) == {"version", "ixps", "rib", "priors", "declared", "order", "queries"})
    check(type(data["version"]) is int and data["version"] == 1)

    ixps = set()
    for a in data["ixps"]:
        check(type(a) is int and 1 <= a <= 4294967295 and a not in ixps)
        ixps.add(a)
    check(len(ixps) <= 1024)

    check(type(data["rib"]) is list and len(data["rib"]) <= 2000)
    rib = []
    total = 0
    for rec in data["rib"]:
        check(type(rec) is dict and set(rec) == {"path", "count"})
        p, c = rec["path"], rec["count"]
        check(type(p) is list and len(p) <= 64)
        for a in p:
            check(type(a) is int and 1 <= a <= 4294967295)
        check(type(c) is int and 1 <= c <= 1000000)
        total += len(p)
        rib.append((tuple(p), c))
    check(total <= 40000)

    check(type(data["priors"]) is list and len(data["priors"]) <= 2000)
    priors = {}
    for rec in data["priors"]:
        check(type(rec) is dict and set(rec) == {"link", "weights"})
        link, w = rec["link"], rec["weights"]
        check(type(link) is list and len(link) == 2)
        u, v = link
        check(type(u) is int and type(v) is int)
        check(1 <= u <= 4294967295 and 1 <= v <= 4294967295 and u != v)
        check(type(w) is list and len(w) == 3)
        for x in w:
            check(type(x) is int and 0 <= x <= 1000000)
        s = sum(w)
        check(s >= 1)
        key = canon(u, v)
        check(key not in priors)
        if u < v:
            vec = tuple(Fraction(x, s) for x in w)
        else:
            vec = tuple(Fraction(x, s) for x in reversed(w))
        priors[key] = vec

    check(type(data["declared"]) is list and len(data["declared"]) <= 2000)
    declared = {}
    for rec in data["declared"]:
        check(type(rec) is dict and set(rec) == {"link", "rel"})
        link, rel = rec["link"], rec["rel"]
        check(type(link) is list and len(link) == 2)
        u, v = link
        check(type(u) is int and type(v) is int)
        check(1 <= u <= 4294967295 and 1 <= v <= 4294967295 and u != v)
        check(type(rel) is str and rel in ("c2p", "p2p", "p2c"))
        key = canon(u, v)
        check(key not in declared)
        slot = {"c2p": 0, "p2p": 1, "p2c": 2}[rel]
        if u > v:
            slot = 2 - slot
        declared[key] = tuple(Fraction(1) if i == slot else Fraction(0) for i in range(3))

    check(type(data["order"]) is list)
    order_pairs = []
    for rec in data["order"]:
        check(type(rec) is list and len(rec) == 2)
        u, v = rec
        check(type(u) is int and type(v) is int)
        check(1 <= u <= 4294967295 and 1 <= v <= 4294967295 and u < v)
        order_pairs.append((u, v))
    check(len(set(order_pairs)) == len(order_pairs))

    check(type(data["queries"]) is list and len(data["queries"]) <= 512)
    queries = []
    ids = set()
    for rec in data["queries"]:
        check(type(rec) is dict and set(rec) == {"id", "path", "threshold"})
        qid, p, th = rec["id"], rec["path"], rec["threshold"]
        check(type(qid) is str and 1 <= len(qid) <= 64)
        for ch in qid:
            check(ch.isascii() and (ch.isalnum() or ch in "_.-"))
        check(qid not in ids)
        ids.add(qid)
        check(type(p) is list and len(p) <= 64)
        for a in p:
            check(type(a) is int and 1 <= a <= 4294967295)
        check(type(th) is list and len(th) == 2)
        a, b = th
        check(type(a) is int and type(b) is int)
        check(0 <= a <= b <= 1000000 and b >= 1)
        queries.append((qid, tuple(p), (a, b)))
    return ixps, rib, priors, declared, order_pairs, queries


def peel_ref(agg):
    links = set()
    for p in agg:
        for i in range(len(p) - 1):
            links.add(canon(p[i], p[i + 1]))
    rounds = {}
    cur = dict(agg)
    rnd = 0
    while True:
        occ = {}
        for p in cur:
            for i in range(len(p) - 1):
                occ.setdefault(canon(p[i], p[i + 1]), []).append(p)
        marked = set()
        for key, plist in occ.items():
            u, v = key
            if all(p[0] == u or p[-1] == u for p in plist):
                marked.add(key)
            elif all(p[0] == v or p[-1] == v for p in plist):
                marked.add(key)
        if not marked:
            break
        rnd += 1
        for k in marked:
            rounds[k] = rnd
        nxt = {}
        for p, c in cur.items():
            lo = 1 if canon(p[0], p[1]) in marked else 0
            hi = len(p) - 1 if canon(p[-2], p[-1]) in marked else len(p)
            q = p[lo:hi]
            if len(q) >= 2:
                nxt[q] = nxt.get(q, 0) + c
        cur = nxt
    return cur, rounds, links


def build_occs(final, core):
    pos = {e: i for i, e in enumerate(core)}
    occs = {e: [] for e in core}
    for p, w in final.items():
        for i in range(len(p) - 1):
            e = canon(p[i], p[i + 1])
            occs[e].append((p, w, i))
    return occs, pos


def phi_value(e, occs, assign):
    u, v = e
    total = 0
    for (p, w, i) in occs:
        a, b = p[i], p[i + 1]
        forward = (a == u)
        if i == 0:
            Ls = 0
        else:
            key = canon(p[i - 1], a)
            st = assign[key]
            Ls = st if p[i - 1] == key[0] else 2 - st
        if i + 2 >= len(p):
            Rs = 2
        else:
            key = canon(b, p[i + 2])
            st = assign[key]
            Rs = st if b == key[0] else 2 - st
        g = GTAB[Ls][Rs]
        center = assign[e] if forward else 2 - assign[e]
        if center == g:
            total += w
    return total


def infer_bruteforce(final, core):
    occs, _ = build_occs(final, core)
    m = len(core)
    Z = 0
    marg = [Fraction(0), Fraction(0), Fraction(0)] if m == 1 else None
    margs = [[0, 0, 0] for _ in range(m)]
    for combo in itertools.product(range(3), repeat=m):
        assign = {core[j]: combo[j] for j in range(m)}
        w = 1
        for j in range(m):
            w *= phi_value(core[j], occs, assign)
        if w == 0:
            continue
        Z += w
        for j in range(m):
            margs[j][combo[j]] += w
    return Z, margs


def check_width(core, scopes, order_pairs):
    adj = {e: set() for e in core}
    for e, sc in scopes.items():
        for x in sc:
            for y in sc:
                if x != y:
                    adj[x].add(y)
    for pair in order_pairs:
        x = pair
        cur = set(adj[x])
        if len(cur) > 4:
            raise Invalid()
        cl = sorted(cur)
        for i in range(len(cl)):
            for j in range(i + 1, len(cl)):
                adj[cl[i]].add(cl[j])
                adj[cl[j]].add(cl[i])
        for y in cur:
            adj[y].discard(x)
        adj[x] = set()


def solve(data):
    ixps, rib, priors, declared, order_pairs, queries = validate(data)
    agg = {}
    for p, c in rib:
        q = norm(p, ixps)
        if len(q) < 2 or len(set(q)) != len(q):
            continue
        t = tuple(q)
        agg[t] = agg.get(t, 0) + c
    final, rounds, links = peel_ref(agg)
    check(len(links) <= 4096)
    core = sorted(k for k in links if k not in rounds)
    check(len(core) <= 64)
    check(sorted(order_pairs) == core and len(order_pairs) == len(core))

    marginals = {}
    if core:
        occs, pos = build_occs(final, core)
        scopes = {}
        for e in core:
            sc = {e}
            for (p, w, i) in occs[e]:
                if i > 0:
                    sc.add(canon(p[i - 1], p[i]))
                if i + 2 < len(p):
                    sc.add(canon(p[i + 1], p[i + 2]))
            scopes[e] = sc
        check_width(core, scopes, order_pairs)
        Z, margs = infer_bruteforce(final, core)
        if Z == 0:
            return {"error": "zero-partition"}
        for j, e in enumerate(core):
            marginals[e] = tuple(Fraction(x, Z) for x in margs[j])

    out_links = []
    for key in sorted(links):
        r = rounds.get(key, 0)
        if r == 0:
            prob = marginals[key]
        else:
            prob = priors.get(key, UNIFORM)
        out_links.append({"link": [key[0], key[1]], "round": r,
                          "prob": [float(x) for x in prob]})

    out_queries = []
    for qid, p, th in queries:
        qn = norm(p, ixps)
        if len(set(qn)) != len(qn):
            out_queries.append({"id": qid, "path": list(qn), "status": "loop",
                                "score": None, "full": None, "witness": None,
                                "leaked": None})
            continue
        if len(qn) < 3:
            out_queries.append({"id": qid, "path": list(qn), "status": "ok",
                                "score": 1.0, "full": 1.0, "witness": None,
                                "leaked": False})
            continue
        probs = []
        for a, b in zip(qn, qn[1:]):
            key = canon(a, b)
            if key in declared:
                vec = declared[key]
            elif key in marginals:
                vec = marginals[key]
            elif key in priors:
                vec = priors[key]
            else:
                vec = UNIFORM
            if a > b:
                vec = (vec[2], vec[1], vec[0])
            probs.append(vec)
        triples = [probs[i][0] + probs[i + 1][2] - probs[i][0] * probs[i + 1][2]
                   for i in range(len(probs) - 1)]
        score = min(triples)
        witness = triples.index(score)
        # full: split sums, computed independently
        n = len(probs)
        full = Fraction(0)
        for k in range(n + 1):  # c2p* p2c* with k leading c2p
            wgt = Fraction(1)
            for i in range(k):
                wgt *= probs[i][0]
            for i in range(k, n):
                wgt *= probs[i][2]
            full += wgt
        for k in range(n):  # c2p* p2p p2c*, p2p at position k
            wgt = probs[k][1]
            for i in range(k):
                wgt *= probs[i][0]
            for i in range(k + 1, n):
                wgt *= probs[i][2]
            full += wgt
        out_queries.append({"id": qid, "path": list(qn), "status": "ok",
                            "score": float(score), "full": float(full),
                            "witness": witness,
                            "leaked": score < Fraction(*th)})
    return {"version": 1, "links": out_links, "queries": out_queries}


if __name__ == "__main__":
    raw = sys.stdin.buffer.read()
    try:
        data = json.loads(raw)
        ans = solve(data)
    except Invalid:
        ans = {"error": "invalid"}
    print(json.dumps(ans, allow_nan=False))
